"""Metrics service to read training telemetry and metrics."""
import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional, List

logger = logging.getLogger(__name__)


class MetricsService:
    def __init__(self, workspace_dir: Path):
        self.workspace_dir = workspace_dir
        self.state_dir = workspace_dir / "experiments" / "state"
        self.logs_dir = workspace_dir / "logs"

    def get_live_state(self, experiment_name: str = "crafter_lstm_ppo") -> Dict[str, Any]:
        """Read the live state file generated by RecordingStorage."""
        state_file = self.state_dir / f"{experiment_name}_state.json"
        if not state_file.exists():
            # Try default or generic search
            candidates = list(self.state_dir.glob("*_state.json"))
            if candidates:
                state_file = candidates[0]
            else:
                return {
                    "status": "idle",
                    "global_step": 0,
                    "episode_count": 0,
                    "update_count": 0,
                    "mean_reward": 0.0,
                    "mean_ep_length": 0.0,
                    "crafter_score": 0.0,
                    "fps": 0.0,
                    "policy_loss": 0.0,
                    "value_loss": 0.0,
                    "entropy": 0.0,
                    "approx_kl": 0.0,
                    "experiment_name": experiment_name,
                }

        try:
            with open(state_file, "r") as f:
                return json.load(f)
        except Exception as e:
            logger.error(f"Error reading state file {state_file}: {e}")
            return {"status": "error", "error": str(e)}

    def get_full_metrics(self, experiment_name: str = "crafter_lstm_ppo") -> Dict[str, Any]:
        """Read comprehensive metrics history from the logs dir."""
        metrics_file = self.logs_dir / f"{experiment_name}_metrics.json"
        if not metrics_file.exists():
            candidates = list(self.logs_dir.glob("*_metrics.json"))
            if candidates:
                metrics_file = candidates[0]
            else:
                return {
                    "experiment_name": experiment_name,
                    "total_steps": 0,
                    "total_episodes": 0,
                    "crafter_score": 0.0,
                    "episode_stats": {},
                    "achievement_rates": {},
                    "update_stats": {},
                    "recent_rewards": [],
                    "recent_lengths": [],
                    "recent_losses": [],
                }

        try:
            with open(metrics_file, "r") as f:
                data = json.load(f)

            rewards = data.get("episode_rewards", [])
            lengths = data.get("episode_lengths", [])
            steps = data.get("episode_steps", [])
            achievements = data.get("achievement_records", {})
            updates = data.get("update_metrics", [])

            # Compute achievement rates
            rates = {}
            for name, records in achievements.items():
                rates[name] = sum(records) / len(records) if records else 0.0

            return {
                "experiment_name": experiment_name,
                "total_steps": steps[-1] if steps else 0,
                "total_episodes": len(rewards),
                "crafter_score": data.get("crafter_score", 0.0),
                "recent_rewards": rewards[-200:],
                "recent_lengths": lengths[-200:],
                "achievement_rates": rates,
                "recent_losses": updates[-100:],
            }
        except Exception as e:
            logger.error(f"Error reading metrics from {metrics_file}: {e}")
            return {"error": str(e)}

